import{_ as n,l,o as e,c as r,v as t,p as s,x as o,d,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"透镜致密化与寿命","description":"","frontmatter":{"title":"透镜致密化与寿命","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/lens-compaction.md","filePath":"litho/lens-compaction.md","lastUpdated":1789023840000}'),h={name:"litho/lens-compaction.md"};function m(_,a,E,u,f,A){const i=l("Mermaid");return e(),r("div",null,[a[1]||(a[1]=t('<h1 id="透镜致密化与寿命" tabindex="-1">透镜致密化与寿命 <a class="header-anchor" href="#透镜致密化与寿命" aria-label="Permalink to &quot;透镜致密化与寿命&quot;">​</a></h1><div class="epigraph"><p>193 nm 在熔石英里会诱发致密化：密度与折射率缓慢爬升，像差变成剂量的积分，不是温度的函数。</p><footer>—— 对照 fused silica compaction under DUV；与可逆 [透镜加热](/litho/lens-heating-compensation) 对照</footer></div><p><a href="/litho/aberration-manipulators">上一课</a>把可逆调节写完。缺口是不可逆：长时间 193 nm 辐照导致玻璃网络致密化（compaction）或相关损伤。本课钉寿命，材料牌号留给下一课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>加热关掉灯就回。致密化积分光子，焦点和球差单调爬，操纵器行程被吃光后必须换组或降规格。把半年 CD 漂移全写成胶或热板，会漏掉镜头剂量史。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>运行：跟踪累计能量、限制不必要的高剂量测试、用低吸收材料（下一课）。监测：定期像差计量，看不可用加热模型解释的残差。寿命以「可维持 NA/像差规格的脉冲或年」记账，不是日历保修空话。</p>',7)),(e(),s(p,null,{default:o(()=>[c(i,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20DOSE%5B%22%E7%B4%AF%E8%AE%A1%20193%20nm%22%5D%20--%3E%20COMP%5B%22%E8%87%B4%E5%AF%86%E5%8C%96%22%5D%0A%20%20COMP%20--%3E%20N%5B%22n%20%E4%B8%8E%E9%9D%A2%E5%BD%A2%E7%BC%93%E5%8F%98%22%5D%0A%20%20N%20--%3E%20LIFE%5B%22%E6%93%8D%E7%BA%B5%E5%99%A8%E8%A1%8C%E7%A8%8B%E8%80%97%E5%B0%BD%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p><span class="marginnote">浸没末片还多一层：水、污染物、镀膜。致密化主要谈体材料；污染是再后一课。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>DUV 在缺陷/杂质处打断网络，结构弛豫使密度升，\\(n\\) 升，等效光焦度漂。空间上跟强度分布走，所以也是「图形相关」的慢效应，但时间尺度是月，不是分钟。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>下一课为何用熔石英与 CaF₂，是致密化与透过率的材料解。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>致密化是剂量积分的永久 \\(n\\) 漂移，与热可逆效应分账。</li><li>寿命表现为操纵器余量和像差规格。</li><li>出处：熔石英 DUV compaction 通识；加热课对照。</li></ul>',7))])}const T=n(h,[["render",m]]);export{D as __pageData,T as default};
